 internal static class UI {
  internal static SolidColorBrush Brush(string hex) {return (SolidColorBrush)new BrushConverter().ConvertFromString(hex);}
  internal static Brush Ink {get{return (Brush)Application.Current.Resources["Ink"];}}
  internal static Brush Muted {get{return (Brush)Application.Current.Resources["Muted"];}}
  internal static Brush Surface {get{return (Brush)Application.Current.Resources["Surface"];}}
  internal static Brush Line {get{return (Brush)Application.Current.Resources["Line"];}}
  internal static Brush Accent {get{return (Brush)Application.Current.Resources["Accent"];}}
  internal static Brush OnAccent {get{return (Brush)Application.Current.Resources["OnAccent"];}}
  internal static bool Dark {get;private set;}
  internal static void Theme(bool dark) {
   Dark=dark;var r=Application.Current.Resources;
   r["Ink"]=Brush(dark?"#F5F3FA":"#24212C"); r["Muted"]=Brush(dark?"#B1ACBD":"#6F6878");
   r["Surface"]=Brush(dark?"#27252E":"#FFFFFF"); r["Page"]=Brush(dark?"#1D1B23":"#F8F7FB");
   r["Line"]=Brush(dark?"#403B4B":"#E8E4ED"); r["Accent"]=Brush(dark?"#BFA6FF":"#7551CE"); r["Tint"]=Brush(dark?"#393044":"#F0EAFB");
   r["OnAccent"]=Brush(dark?"#211B2D":"#FFFFFF");r["ScrollThumb"]=Brush(dark?"#82788F":"#8E849B");
   foreach(Window window in Application.Current.Windows)UpdateWindowFrame(window);
  }
  internal static void Init() {
   const string xaml=@"<ResourceDictionary xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'>
<Style TargetType='Window'><Setter Property='FontFamily' Value='Segoe UI'/><Setter Property='FontSize' Value='14'/><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='Background' Value='{DynamicResource Page}'/></Style>
