<Style TargetType='TextBox'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='CaretBrush' Value='{DynamicResource Ink}'/><Setter Property='Background' Value='{DynamicResource Surface}'/><Setter Property='BorderBrush' Value='{DynamicResource Line}'/><Setter Property='BorderThickness' Value='1'/><Setter Property='Padding' Value='10,8'/><Setter Property='VerticalContentAlignment' Value='Center'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='TextBox'><Border x:Name='b' CornerRadius='7' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}'><ScrollViewer x:Name='PART_ContentHost' Margin='0' Focusable='False'/></Border><ControlTemplate.Triggers><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='b' Property='BorderBrush' Value='{DynamicResource Accent}'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter Property='Foreground' Value='{DynamicResource Muted}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
<Style TargetType='ComboBox'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='Background' Value='{DynamicResource Surface}'/><Setter Property='MinHeight' Value='36'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBox'><Grid><Border Background='{TemplateBinding Background}' BorderBrush='{DynamicResource Line}' BorderThickness='1' CornerRadius='7'><Grid><ContentPresenter Margin='10,7,25,7' Content='{TemplateBinding SelectionBoxItem}' VerticalAlignment='Center'/><TextBlock Text='⌄' HorizontalAlignment='Right' VerticalAlignment='Center' Margin='0,0,10,0' Foreground='{DynamicResource Muted}'/></Grid></Border><ToggleButton Focusable='False' IsChecked='{Binding IsDropDownOpen,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}'><ToggleButton.Template><ControlTemplate TargetType='ToggleButton'><Border Background='Transparent'/></ControlTemplate></ToggleButton.Template></ToggleButton><Popup IsOpen='{TemplateBinding IsDropDownOpen}' Placement='Bottom' AllowsTransparency='True' Focusable='False' PopupAnimation='Fade'><Border MinWidth='{Binding ActualWidth,RelativeSource={RelativeSource TemplatedParent}}' Background='{DynamicResource Surface}' BorderBrush='{DynamicResource Line}' BorderThickness='1' CornerRadius='8' Padding='4' Margin='0,3,0,0'><StackPanel IsItemsHost='True'/></Border></Popup></Grid></ControlTemplate></Setter.Value></Setter></Style><Style TargetType='ComboBoxItem'><Setter Property='Padding' Value='10,8'/><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ComboBoxItem'><Border x:Name='b' CornerRadius='5' Padding='{TemplateBinding Padding}' Background='Transparent'><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property='IsHighlighted' Value='True'><Setter TargetName='b' Property='Background' Value='{DynamicResource Tint}'/></Trigger><Trigger Property='IsSelected' Value='True'><Setter TargetName='b' Property='Background' Value='{DynamicResource Tint}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
<Style TargetType='CheckBox'><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='Margin' Value='0,4,0,4'/></Style>
<Style TargetType='ScrollBar'><Setter Property='Width' Value='12'/><Setter Property='Background' Value='Transparent'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ScrollBar'><Grid Background='{TemplateBinding Background}'><Track x:Name='PART_Track' Orientation='{TemplateBinding Orientation}' IsDirectionReversed='True'><Track.DecreaseRepeatButton><RepeatButton x:Name='Decrease' Command='ScrollBar.PageUpCommand' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Background='Transparent'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.Thumb><Thumb x:Name='Thumb' MinHeight='24' Background='{DynamicResource ScrollThumb}'><Thumb.Template><ControlTemplate TargetType='Thumb'><Border x:Name='ThumbBorder' Background='{TemplateBinding Background}' CornerRadius='3' Margin='3,2'/><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='ThumbBorder' Property='Background' Value='{DynamicResource Accent}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton x:Name='Increase' Command='ScrollBar.PageDownCommand' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Background='Transparent'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton></Track></Grid><ControlTemplate.Triggers><Trigger Property='Orientation' Value='Horizontal'><Setter TargetName='PART_Track' Property='IsDirectionReversed' Value='False'/><Setter TargetName='Decrease' Property='Command' Value='ScrollBar.PageLeftCommand'/><Setter TargetName='Increase' Property='Command' Value='ScrollBar.PageRightCommand'/><Setter TargetName='Thumb' Property='MinHeight' Value='0'/><Setter TargetName='Thumb' Property='MinWidth' Value='24'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter><Style.Triggers><Trigger Property='Orientation' Value='Horizontal'><Setter Property='Width' Value='Auto'/><Setter Property='Height' Value='12'/></Trigger></Style.Triggers></Style>
<Style TargetType='Slider'><Setter Property='MinHeight' Value='28'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='Slider'><Grid Height='28' Background='Transparent'><Track x:Name='PART_Track' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{Binding Value,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}'><Track.DecreaseRepeatButton><RepeatButton Command='Slider.DecreaseLarge' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Height='4' CornerRadius='2' Background='{DynamicResource Accent}'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton><Track.Thumb><Thumb Width='12' Height='22'><Thumb.Template><ControlTemplate TargetType='Thumb'><Border Background='{DynamicResource Accent}' CornerRadius='5' BorderBrush='{DynamicResource Surface}' BorderThickness='2'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command='Slider.IncreaseLarge' Focusable='False'><RepeatButton.Template><ControlTemplate TargetType='RepeatButton'><Border Height='4' CornerRadius='2' Background='{DynamicResource Line}'/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton></Track></Grid></ControlTemplate></Setter.Value></Setter></Style>
</ResourceDictionary>";
   Application.Current.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(xaml));
  }
  internal static void ApplyWindowTheme(Window window) {
   window.SetResourceReference(FrameworkElement.StyleProperty,typeof(Window));
   window.SourceInitialized+=delegate{UpdateWindowFrame(window);};window.Loaded+=delegate{UpdateWindowFrame(window);};
  }
  private static void UpdateWindowFrame(Window window) {
   if(window.AllowsTransparency)return;
   var source=PresentationSource.FromVisual(window) as System.Windows.Interop.HwndSource;
   if(source==null || source.IsDisposed)return;var handle=source.Handle;if(handle==IntPtr.Zero)return;
   int dark=Dark?1:0,round=2;
   Native.DwmSetWindowAttribute(handle,20,ref dark,4);Native.DwmSetWindowAttribute(handle,33,ref round,4);
  }
  internal static void Primary(Button button) {
   button.SetResourceReference(Control.BackgroundProperty,"Accent");button.SetResourceReference(Control.ForegroundProperty,"OnAccent");button.BorderThickness=new Thickness(0);
  }
  internal static TextBlock Text(string t,double size,Brush color) {return new TextBlock{Text=t,FontSize=size,Foreground=color,TextWrapping=TextWrapping.Wrap};}
  internal static Button Button(string t,Action action) {var b=new Button{Content=t}; b.Click+=delegate{action();}; return b;}
  internal static Border Card(UIElement content) {return new Border{Background=Surface,BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(12),Padding=new Thickness(20),Child=content};}
  internal static FrameworkElement ItemIcon(LaunchItem item,double size) {
   if(item.IsGroup) {
    var icons=new Grid{Width=size,Height=size,ToolTip="Группа приложений"};
    icons.Children.Add(new Border{Background=(Brush)Application.Current.Resources["Tint"],CornerRadius=new CornerRadius(size/5)});
    for(int i=0;i<Math.Min(3,item.Children.Count);i++){var child=ItemIcon(item.Children[i],size*.53);child.HorizontalAlignment=i==1?HorizontalAlignment.Right:HorizontalAlignment.Left;child.VerticalAlignment=i==2?VerticalAlignment.Bottom:VerticalAlignment.Top;icons.Children.Add(child);}
    if(item.Children.Count==0)icons.Children.Add(new TextBlock{Text="▦",Foreground=Accent,FontSize=size*.7,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center});
    return icons;
   }
   var icon=Native.Icon(item.IconTarget??item.Target)??Native.Icon(item.Target); if(icon!=null) return new Image{Source=icon,Width=size,Height=size,Stretch=Stretch.Uniform};
   return new Border{Width=size,Height=size,CornerRadius=new CornerRadius(8),Background=(Brush)Application.Current.Resources["Tint"],Child=new TextBlock{Text=item.Name.Substring(0,1).ToUpperInvariant(),Foreground=Accent,FontSize=size*.55,FontWeight=FontWeights.SemiBold,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center}};
  }
 }
